-- public.thread_participants RLS
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();

-- Threads: announcement (A), group (G: coach, par1, par3), direct (D: par1 <-> par3)
set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select 1 from public.thread_participants $$, '42501', null, 'anonymous has no access');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.thread_participants where thread_id='71000000-0000-0000-0000-00000000000b'), 3, 'participants see the group roster');
select is((select count(*)::int from public.thread_participants where thread_id='71000000-0000-0000-0000-00000000000c'), 2, 'a direct thread shows both participants');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.thread_participants where true), 0, 'a non-participant sees no participants');
reset role; select set_config('request.jwt.claims', '{"sub":"aa000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.thread_participants where thread_id='71000000-0000-0000-0000-00000000000b'), 3, 'a team admin sees group participants');
select is((select count(*)::int from public.thread_participants where thread_id='71000000-0000-0000-0000-00000000000c'), 0, 'a team admin does not see direct participants');
reset role; select set_config('request.jwt.claims', '{"sub":"dd000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.thread_participants where true), 0, 'another team sees nothing');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ insert into public.thread_participants (thread_id, profile_id, role) values ('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000002','member') $$, '42501', null, 'clients cannot add participants directly');
select throws_ok($$ update public.thread_participants set role='owner' $$, '42501', null, 'clients cannot change roles directly');
select throws_ok($$ delete from public.thread_participants $$, '42501', null, 'clients cannot delete participants directly');
reset role;
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.thread_participants where true), 1, 'an announcement participant row (mute holder) is visible to its owner');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.thread_participants where thread_id='71000000-0000-0000-0000-00000000000a'), 0, 'announcement rows of others are never visible to members');
reset role;
select * from finish();
rollback;
